    assert.equal(allDisposed.assets.length, 0)
    assert.equal(allDisposed.editable, true)
    assert.equal(await client.asset.count({ where: { receiptId: unitReport.id } }), 0)
    assert.equal(await client.disposalItem.count({ where: { inspectionId: unitReport.id } }), unitRows.length)
    const recovered = await inspections.save(unitReport.id, inspectionWrite.parse({ version: allDisposed.version, rows: unitRows.map((entry) => ({ ...entry, unit: 'SET' })), reason: '단위 변경 및 재사용 복원' }), reviewer, true)
    assert.equal(recovered.assets.length, unitRows.length)
    assert.equal(await client.disposal.count({ where: { inspectionId: unitReport.id } }), 0)
    assert.equal(await client.asset.count({ where: { receiptId: unitReport.id, unit: 'SET' } }), unitRows.length)
    assert.equal(recovered.assets.some((entry) => unitResult.assets.some((previous) => previous.id === entry.id)), false)
    const third = await create('2026-09-25')
